<?php require __DIR__.'/includes/bootstrap.php';require_role('customer');$serviceId=intval($_GET['service']??0);$service=$pdo->prepare("SELECT * FROM services WHERE id=? AND active=1");$service->execute([$serviceId]);$service=$service->fetch();if(!$service){flash('Please select a valid service.','error');redirect('services.php');}if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$date=$_POST['date'];$time=$_POST['time'];if($date<date('Y-m-d')){flash('Please choose a future date.','error');}else{$stmt=$pdo->prepare("INSERT INTO customer_addresses(customer_id,label,house,area,city,state,postal_code) VALUES(?,?,?,?,?,?,?)");$stmt->execute([current_user()['id'],$_POST['label']??'Home',$_POST['house'],$_POST['area'],$_POST['city'],$_POST['state'],$_POST['postal_code']]);$addressId=$pdo->lastInsertId();$total=$service['price']+$service['visit_charge'];$code='NH'.date('ymd').strtoupper(bin2hex(random_bytes(3)));$pdo->beginTransaction();$stmt=$completionOtp=random_int(100000,999999);$pdo->prepare("INSERT INTO bookings(booking_code,customer_id,service_id,address_id,problem_description,booking_date,booking_time,visit_charge,service_amount,total_amount,payment_method,completion_otp_hash) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)");$stmt->execute([$code,current_user()['id'],$serviceId,$addressId,trim($_POST['problem']),$date,$time,$service['visit_charge'],$service['price'],$total,$_POST['payment_method'],password_hash((string)$completionOtp,PASSWORD_DEFAULT)]);$id=$pdo->lastInsertId();$categoryWorker=$pdo->prepare("SELECT w.id FROM workers w JOIN services s ON s.category_id=(SELECT id FROM service_categories WHERE slug=w.category) WHERE w.status='approved' AND s.id=? ORDER BY ABS(COALESCE(w.starting_price,299)-?) ASC, w.id ASC LIMIT 1");$categoryWorker->execute([$serviceId,$service['price']]);$matchedWorker=$categoryWorker->fetchColumn();if($matchedWorker){$pdo->prepare("UPDATE bookings SET worker_id=?,status='Worker Assigned' WHERE id=?")->execute([$matchedWorker,$id]);$pdo->prepare("INSERT INTO booking_status_history(booking_id,status) VALUES(?,'Worker Assigned')")->execute([$id]);}else{$pdo->prepare("INSERT INTO booking_status_history(booking_id,status) VALUES(?, 'Pending')")->execute([$id]);}$pdo->commit();flash('Booking confirmed. ID: '.$code.'. Your job completion OTP is '.$completionOtp.'. Do not share it until the worker finishes the service.');redirect('my-bookings.php');}}$pageTitle='Book service';require __DIR__.'/includes/header.php'; ?>
<div class="auth-wrap"><form method="post" class="auth-card" style="max-width:650px"><h1>Book <?=e($service['name'])?></h1><p class="auth-alt">Visit charge ₹<?=number_format($service['visit_charge'],0)?> · Service from ₹<?=number_format($service['price'],0)?> · Total shown before approved extras</p><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label class="field"><span>Describe the problem</span><textarea name="problem" required></textarea></label><div class="form-grid"><label class="field"><span>House / building</span><input name="house" required></label><label class="field"><span>Street / area</span><input name="area" required></label><label class="field"><span>City</span><input name="city" required></label><label class="field"><span>State</span><input name="state" required></label><label class="field"><span>Postal code</span><input name="postal_code" required></label><label class="field"><span>Booking date</span><input type="date" name="date" min="<?=date('Y-m-d')?>" required></label><label class="field"><span>Time slot</span><select name="time"><option>09:00:00</option><option>11:00:00</option><option>14:00:00</option><option>17:00:00</option></select></label><label class="field"><span>Payment</span><select name="payment_method"><option value="cash">Cash</option><option value="online" disabled>Online (configure gateway)</option></select></label></div><button class="btn btn-primary">Confirm booking · ₹<?=number_format($service['price']+$service['visit_charge'],0)?></button></form></div><?php require __DIR__.'/includes/footer.php'; ?>